#include "domain/persistence.hpp"
#include "json.hpp"
#include <fstream>
#include <iostream>
using namespace stalthos;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(int argc,char**argv){try{check(argc==3,"usage legacy.stl migration.json");const auto save=persistence::readSave(argv[1]);check(save.resourceLedger.has_value(),"old save ledger absent");std::ifstream stream(argv[2]);nlohmann::json evidence;stream>>evidence;const auto&ledger=evidence.at("resource_ledger_initial");check(ledger.at("resources").size()==save.resourceLedger->resources.size(),"resource count changed");check(ledger.at("sessions").size()==save.resourceLedger->sessions.size(),"history count changed");for(size_t i=0;i<save.resourceLedger->resources.size();++i){const auto&a=save.resourceLedger->resources[i];const auto&b=ledger.at("resources").at(i);check(a.id==b.at("id").get<uint64_t>()&&unsigned(a.kind)==b.at("kind").get<unsigned>()&&a.initialQuantity==b.at("initial_quantity").get<double>()&&a.consumedQuantity==b.at("consumed_quantity").get<double>(),"resource record changed");}for(size_t i=0;i<save.resourceLedger->sessions.size();++i){const auto&a=save.resourceLedger->sessions[i];const auto&b=ledger.at("sessions").at(i);check(a.sessionId==b.at("session_id").get<uint64_t>()&&a.resourceId==b.at("resource_id").get<uint64_t>()&&a.amount==b.at("amount").get<double>(),"history record changed");}auto saved=save.faunaResourceSessions;auto migrated=evidence.at("resource_sessions_initial").get<std::vector<std::pair<Identity,uint64_t>>>();std::sort(saved.begin(),saved.end());std::sort(migrated.begin(),migrated.end());check(saved==migrated,"saved ownership mappings changed");std::cout<<"LEGACY_NATIVE_EXACT_LEDGER_OK resources="<<save.resourceLedger->resources.size()<<" history="<<save.resourceLedger->sessions.size()<<" bindings="<<saved.size()<<"\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
